def plot(rows, B, C, E):
    labels = list(rows[0]['links'])
    values = np.array([[{'FAIL': 0, 'UNKNOWN': 1, 'PASS': 2}[r['links'][k]['status']] for k in labels] for r in rows])
    (fig, axes) = plt.subplots(1, 3, figsize=(18, 10), gridspec_kw={'width_ratios': [2.0, 1.05, 1.05]})
    from matplotlib.colors import ListedColormap
    ax = axes[0]
    ax.imshow(values, cmap=ListedColormap(['#c94a48', '#c8cbd0', '#41a579']), vmin=0, vmax=2, aspect='auto')
    ax.set_xticks(range(len(labels)), labels, rotation=55, ha='right')
    ax.set_yticks(range(len(rows)), [('R4 ' if r['cohort'] == 'R4_PRIMARY' else 'B2B ') + r['case_key'][:4] + ' /' + str(r['fdi']) for r in rows], fontsize=8)
    for i in range(len(rows)):
        for j in range(len(labels)):
            ax.text(j, i, ['F', '?', 'P'][values[i, j]], ha='center', va='center', fontsize=8)
    ax.axhline(17.5, color='black')
    ax.set_title('Same-case links: 0/18 primary; 0/4 auxiliary qualified\nP/F model scope retained; ? missing physical inputs')
    ax = axes[1]
    need = [r['minimum_total_surface_motion_necessary_mm'] * 1000 for r in B['rows']]
    ax.barh(range(18), need, color='#c94a48')
    ax.axvline(50, color='black', label='X82 exterior edit50um')
    ax.axvline(100, color='#355b86', label='both surfaces50um')
    ax.set_xlabel('Necessary total surface motion (um)\nPER_POINT exact witness, stored geometry')
    ax.set_yticks([])
    ax.invert_yaxis()
    ax.set_title('Height adjustment cannot repair R4 wall')
    ax.legend(fontsize=8)
    ax = axes[2]
    q = E['published_fracture_rows']
    ax.scatter([r['thickness_mm'] for r in q], [r['q05_N'] for r in q], color='#355b86')
    ax.errorbar([r['thickness_mm'] for r in q], [r['q05_N'] for r in q], yerr=np.array([[r['q05_N'] - r['parameter_rectangle_q05_N'][0] for r in q], [r['parameter_rectangle_q05_N'][1] - r['q05_N'] for r in q]]), fmt='none', color='#355b86')
    ax.set_xlabel('Published nominal thickness (mm)')
    ax.set_ylabel('5% failure-load quantile (N), POPULATION')
    ax.set_title('Prott Table1 source populations\nNot patient-crown predictions')
    ax.text(0.03, 0.92, 'Parameter rectangle, not a prediction band', transform=ax.transAxes, fontsize=8)
    fig.tight_layout()
    fig.savefig(ROOT / 'figures/CROWN_CHAIN.png', dpi=150)
    fig.savefig(ROOT / 'figures/CROWN_CHAIN.pdf')
    plt.close(fig)

def write_docs(result, A, B, C, E):
    lines = ['# Same-case crown chain', '', '**No full crown qualifies: 0/18 primary R4 teeth across 6 jaws, and 0/4 separate Bits2Bites specimens across 2 jaws.** All 22 are retained in the case table. Physical outcomes were not measured. The external geometric reference is the original published tooth surface, not a synthetic preparation.', '', 'Run `./run_all.sh` from this directory. It calls read-only reviewed package functions, recomputes all 18 primary and 4 auxiliary records, executes actual fault controls, redraws the figure and checks the frozen physical-null predictions. Requires the existing pinned scientific Python, bubblewrap and local datasets. No network, GPU, source edits, tree copies or data downloads.', '', '|Link (PER_TOOTH counts)|R4 primary 18|Bits2Bites auxiliary 4|What supports it|', '|---|---:|---:|---|']
    for k in result['counts']['R4_PRIMARY']:
        a = result['counts']['R4_PRIMARY'][k]
        b = result['counts']['BITS2BITES_AUXILIARY'][k]
        lines.append('|' + k + '|' + ', '.join((f'{v} {s}' for (s, v) in a.items())) + '|' + ', '.join((f'{v} {s}' for (s, v) in b.items())) + '|' + {'shape': 'Published native surface; modeled reconstruction', 'margin': 'Virtual margin only', 'wall': 'Exact failure witness R4; conditional numerical bound auxiliary', 'insertion': 'Exact finite-normal Farkas model only', 'milling': 'Sampled tool-envelope scenarios', 'force': 'Missing same-specimen measurement', 'fracture_q05': 'Published populations cannot transfer', 'cement': 'No seated spatial film', 'lab': 'Protocol/freeze delivered, observations absent'}[k] + '|')
    lo = min((r['minimum_total_surface_motion_necessary_mm'] for r in B['rows']))
    hi = max((r['minimum_total_surface_motion_necessary_mm'] for r in B['rows']))
    lines += ['', '|Question the composition decides|Answer|', '|---|---|'] + [f"|{r['question']}|{r['answer']}|" for r in result['composition_decisions']]
    lines += ['', f'R4 exact stored-coordinate witnesses require at least {lo:.9f}–{hi:.9f} mm total motion at tracked points (PER_POINT). The ±0.05 mm X82 exterior-edit box cannot repair these walls. This does not prohibit a new preparation or different topology. The 12/18 R4 family-envelope passes must not be relabelled as reaching each tooth’s natural floor: that stricter count is 0/18.', '', f"The auxiliary 25 µm calibration probes retain inherited nominal wall lower bounds {min((r['wall_probe_lower_mm'] for r in C['rows'])):.6f}–{max((r['wall_probe_lower_mm'] for r in C['rows'])):.6f} mm (PER_POINT minima aggregated PER_TOOTH). All 4 auxiliary exteriors fail the 0.35 mm legacy shape gate; 3/4 fail native contact gates. They are inherited generated shapes, not four new contralateral reconstructions.", '', 'R4 has no verified bite registration. Bits2Bites has source-registered arches, with unknown loaded-pose error. Neither supplies same-object absolute reaction-force calibration, true preparation, actual tool/CAM scene or seated cement film. MUST/CAN/NEVER therefore remains UNKNOWN for these edited crowns; an absent pair graph must not become NEVER. The reviewed Field classifier is executed on rational discriminating controls. Its broad model force ranges are never substituted for patient measurements.', '', 'Published Prott Table 1 population parameters produce the following lower-tail values. They are mathematically transformed fitted parameters, not fresh measurements or patient-calibrated loads.', '', '|Nominal thickness (mm)|q05 (N)|Parameter-rectangle range (N)|', '|---:|---:|---:|']
    for r in E['published_fracture_rows']:
        lines.append(f"|{r['thickness_mm']}|{r['q05_N']:.3f}|{r['parameter_rectangle_q05_N'][0]:.3f}–{r['parameter_rectangle_q05_N'][1]:.3f}|")
    lines += ['', 'Parameter ranges are the monotone image of the two reported marginal 90% confidence intervals, giving at least 80% simultaneous parameter coverage if those intervals are valid. They are not physical prediction intervals. [Prott 2021 Table 1](https://doi.org/10.4047/jap.2021.13.5.269) supplies the source; local text/hash and exact cells are recorded in raw/REFERENTS.json. X23’s LS2 bar strength remains MPa and fails transfer to 3Y. X13 refuses all 94 primary regional group means as spatial seated film.', '', '![Case links, exact repair obstruction and external force reference](figures/CROWN_CHAIN.png)', '', 'Sufficiency test: two equal-area fields have the identical mean 0.5 mm exactly, with minima 0.25 and 0.5 mm. Identity error 0; downstream difference 0.25 mm. A certified minimum is the smallest extension for that fixed wall decision. For editing and force coupling the local field, incidence and specimen identity must be retained.', '', f"Controls: {len(read(ROOT / 'raw/CONTROLS.json')['controls'])} composition controls, 72 exact witness corruptions and 6 source/interface controls pass; each named fault is actually executed. The same-information numerical controls agree within their frozen tolerances; no algorithm advantage is claimed. Peak measured process RSS {result['cost']['peak_rss_MiB']:.1f} MiB; maximum 4 library threads. Total historical acquisition/fit/reasoning and physical costs are UNKNOWN, not zero.", '', 'Not established: physical crown function, calibrated fracture quantiles per tooth, insertion through a real preparation, continuous CAM access, actual seated film, or lab alarm false-positive rate. R3 wall/shape/contact/tool calculations lack rigorous floating/source-geometry enclosures. Exact R2 certificates refer only to stored digital vertices. The 0.5 mm wall and other inherited thresholds are engineering scenarios, not clinical recommendations.', '', 'Licenses: Teeth3DS local mesh licence UNKNOWN; [source](https://crns-smartvision.github.io/teeth3ds/). Bits2Bites CC BY-NC-SA per upstream contract; [source](https://ditto.ing.unimore.it/bits2bites/). Prott article CC BY-NC 4.0. X23 custom LS2 spreadsheet and X13 local papers keep their individual source terms; nothing is redistributed. No ToothFairy2, mandible or new patient records used.', '', 'Read [LAB_PROTOCOL.md](LAB_PROTOCOL.md), [FROZEN_PREDICTIONS.json](FROZEN_PREDICTIONS.json), [PER_TOOTH.csv](PER_TOOTH.csv) and [HANDOFF.md](HANDOFF.md). Status PENDING_INDEPENDENT_REVIEW.']
